use base64::Engine as _;

use super::*;

// Generated by fixtures/generate.sh with GnuPG 2.4.9. Keys were created on
// 2000-01-01, `past` signatures an hour later and the rest on 2026-10-09.
const GOOD_KEY: &[u8] = include_bytes!("fixtures/good.key.asc");
const PRODUCTION_KEY: &[u8] = include_bytes!("../../../../apps/cli/GPG_PUBLIC_KEY.asc");
const PRODUCTION_FINGERPRINT: &str = "A38FF6BC6623FCA611A7A32B5EFBF0F4A5870815";
// The release key before the 2026-10-10 rotation, which signed v0.3.374.
const RETIRED_FINGERPRINT: &str = "39F95DC66BA8EFBEAF49FAEF39D46239F95F4632";
const DATA: &[u8] = b"release\n";
const PAST: u64 = 946_684_800;
const TODAY: u64 = 1_791_504_000;

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!(
        "{}/src/openpgp/fixtures/{name}",
        env!("CARGO_MANIFEST_DIR")
    ))
    .unwrap()
}

fn fingerprint(name: &str) -> String {
    String::from_utf8(fixture(&format!("{name}.fingerprint")))
        .unwrap()
        .trim()
        .to_owned()
}

fn import(name: &str) -> Result<ReleaseKey> {
    ReleaseKey::import(&fixture(&format!("{name}.key.asc")), &fingerprint(name))
}

fn good() -> ReleaseKey {
    ReleaseKey::import(GOOD_KEY, &fingerprint("good")).unwrap()
}

fn signature(name: &str) -> Vec<u8> {
    fixture(&format!("{name}.sig.asc"))
}

fn armor(bytes: &[u8], label: &str) -> Vec<u8> {
    let engine = base64::engine::general_purpose::STANDARD;
    let body = engine.encode(bytes);
    let mut text = format!("-----BEGIN PGP {label}-----\n\n");
    for line in body.as_bytes().chunks(64) {
        text.push_str(std::str::from_utf8(line).unwrap());
        text.push('\n');
    }
    text.push('=');
    text.push_str(&engine.encode(&crc24(bytes).to_be_bytes()[1..]));
    text.push_str(&format!("\n-----END PGP {label}-----\n"));
    text.into_bytes()
}

fn packet_bytes(name: &str) -> Vec<u8> {
    dearmor(&signature(name), "SIGNATURE").unwrap()
}

#[test]
fn every_sha2_signature_by_the_pinned_primary_verifies_its_exact_bytes() {
    let key = good();
    for name in ["good-sha512", "good-sha384", "good-sha256", "past"] {
        key.verify(DATA, &signature(name)).unwrap();
        assert_eq!(
            key.verify(b"release\n\n", &signature(name)),
            Err(SignatureError::Bad),
            "{name} admitted changed bytes"
        );
    }
}

#[test]
fn compiled_production_key_is_bound_to_its_primary_pin() {
    let key = ReleaseKey::import(PRODUCTION_KEY, PRODUCTION_FINGERPRINT).unwrap();
    assert_eq!(hex(&key.fingerprint), PRODUCTION_FINGERPRINT);
    assert_eq!(bit_length(&key.n), 4096);
    let mut other = PRODUCTION_FINGERPRINT.to_owned();
    other.replace_range(39.., "3");
    assert_eq!(
        ReleaseKey::import(PRODUCTION_KEY, &other).unwrap_err(),
        SignatureError::Key
    );
    assert_eq!(
        ReleaseKey::import(PRODUCTION_KEY, &PRODUCTION_FINGERPRINT.to_lowercase()).unwrap_err(),
        SignatureError::Key
    );
}

#[test]
fn a_published_release_signature_verifies() {
    // SHA256SUMS of v0.3.374 and its signature, as the release job signed
    // and published them with the retired release key (not made by
    // fixtures/generate.sh). The current key refuses it.
    let retired =
        ReleaseKey::import(&fixture("retired-39F95DC6.key.asc"), RETIRED_FINGERPRINT).unwrap();
    let sums = fixture("production-v0.3.374.SHA256SUMS");
    let signature = fixture("production-v0.3.374.SHA256SUMS.asc");
    retired.verify(&sums, &signature).unwrap();
    let mut changed = sums.clone();
    changed[0] ^= 1;
    assert_eq!(
        retired.verify(&changed, &signature),
        Err(SignatureError::Bad)
    );
    assert_eq!(good().verify(&sums, &signature), Err(SignatureError::Bad));
    let current = ReleaseKey::import(PRODUCTION_KEY, PRODUCTION_FINGERPRINT).unwrap();
    assert_eq!(current.verify(&sums, &signature), Err(SignatureError::Bad));
}

#[test]
fn another_key_is_refused_at_import_and_at_verification() {
    let wrong = fixture("wrong.key.asc");
    assert_eq!(
        ReleaseKey::import(&wrong, &fingerprint("good")).unwrap_err(),
        SignatureError::Key
    );
    assert_eq!(
        import("wrong")
            .unwrap()
            .verify(DATA, &signature("good-sha512")),
        Err(SignatureError::Bad)
    );
}

#[test]
fn a_key_that_could_be_limited_never_imports() {
    // Expired since 2000-01-02, revoked, or carrying a signing subkey: the
    // compiled key admits none of them at any time.
    assert_eq!(import("expired").unwrap_err(), SignatureError::KeyUnusable);
    assert_eq!(
        ReleaseKey::import_at(
            &fixture("expired.key.asc"),
            &fingerprint("expired"),
            PAST + 60
        )
        .unwrap_err(),
        SignatureError::KeyUnusable
    );
    assert_eq!(import("revoked").unwrap_err(), SignatureError::KeyUnusable);
    assert_eq!(import("subkey").unwrap_err(), SignatureError::Key);

    // A user ID certified only by another key grants nothing.
    let bytes = dearmor(GOOD_KEY, "PUBLIC KEY BLOCK").unwrap();
    let packets = packets(&bytes).unwrap();
    assert_eq!(
        packets.iter().map(|p| p.tag).collect::<Vec<_>>(),
        [PUBLIC_KEY, USER_ID, SIGNATURE]
    );
    let other = dearmor(&fixture("wrong.key.asc"), "PUBLIC KEY BLOCK").unwrap();
    let other = packets_of(&other);
    let mut foreign = framed(PUBLIC_KEY, packets[0].body);
    foreign.extend(framed(USER_ID, packets[1].body));
    foreign.extend(framed(SIGNATURE, other[2].body));
    assert_eq!(
        ReleaseKey::import(&armor(&foreign, "PUBLIC KEY BLOCK"), &fingerprint("good")).unwrap_err(),
        SignatureError::Key
    );
    // Without its self-certification the key cannot sign.
    let mut bare = framed(PUBLIC_KEY, packets[0].body);
    bare.extend(framed(USER_ID, packets[1].body));
    assert_eq!(
        ReleaseKey::import(&armor(&bare, "PUBLIC KEY BLOCK"), &fingerprint("good")).unwrap_err(),
        SignatureError::KeyUnusable
    );
    // The same packets re-framed in the new format still import.
    let mut reframed = framed(PUBLIC_KEY, packets[0].body);
    reframed.extend(framed(USER_ID, packets[1].body));
    reframed.extend(framed(SIGNATURE, packets[2].body));
    ReleaseKey::import(&armor(&reframed, "PUBLIC KEY BLOCK"), &fingerprint("good")).unwrap();
}

fn packets_of(bytes: &[u8]) -> Vec<Packet<'_>> {
    packets(bytes).unwrap()
}

/// A new-format packet with a five-octet length.
fn framed(tag: u8, body: &[u8]) -> Vec<u8> {
    let mut bytes = vec![0xc0 | tag, 255];
    bytes.extend_from_slice(&u32::try_from(body.len()).unwrap().to_be_bytes());
    bytes.extend_from_slice(body);
    bytes
}

#[test]
fn expired_signature_is_refused_once_its_lifetime_passes() {
    let key = good();
    assert_eq!(
        key.verify(DATA, &signature("expired-signature")),
        Err(SignatureError::Expired)
    );
    key.verify_at(DATA, &signature("expired-signature"), PAST + 7200)
        .unwrap();
}

#[test]
fn a_future_signature_is_accepted_like_gnupg_does() {
    // A client clock behind the signer's must not refuse a fresh release.
    good().verify(DATA, &signature("future")).unwrap();
    good()
        .verify_at(DATA, &signature("good-sha512"), PAST)
        .unwrap();
}

#[test]
fn signature_older_than_its_key_is_refused() {
    let key = good();
    let bytes = packet_bytes("past");
    let mut signature = Signature::parse(&bytes[3..]).unwrap();
    signature.created = key.created - 1;
    assert_eq!(
        key.check(&signature, DATA.to_vec(), TODAY),
        Err(SignatureError::Bad)
    );
}

#[test]
fn sha1_text_mode_clearsigned_and_binary_signatures_are_refused() {
    let key = good();
    assert_eq!(
        key.verify(DATA, &signature("sha1")),
        Err(SignatureError::Bad)
    );
    assert_eq!(
        key.verify(DATA, &signature("text-mode")),
        Err(SignatureError::Bad)
    );
    assert_eq!(
        key.verify(DATA, &signature("clearsigned")),
        Err(SignatureError::Malformed)
    );
    let binary = fixture("binary.sig");
    assert_eq!(key.verify(DATA, &binary), Err(SignatureError::Malformed));
    assert_eq!(
        key.verify(DATA, b"not armor"),
        Err(SignatureError::Malformed)
    );
}

#[test]
fn a_signature_integer_shorter_than_the_modulus_verifies() {
    let bytes = packet_bytes("short-mpi");
    let parsed = Signature::parse(&bytes[3..]).unwrap();
    assert!(parsed.value.len() < good().n.len());
    good()
        .verify(&fixture("short-mpi.data"), &signature("short-mpi"))
        .unwrap();
}

#[test]
fn armor_framing_and_checksum_are_exact() {
    let key = good();
    let text = String::from_utf8(signature("good-sha512")).unwrap();
    let crlf = text.replace('\n', "\r\n");
    assert!(key.verify(DATA, crlf.as_bytes()).is_err());
    let checksum = text.lines().find(|line| line.starts_with('=')).unwrap();
    let mut changed = checksum.to_owned();
    changed.replace_range(1..2, if &checksum[1..2] == "A" { "B" } else { "A" });
    let wrong_crc = text.replace(checksum, &changed);
    assert_eq!(
        key.verify(DATA, wrong_crc.as_bytes()),
        Err(SignatureError::Malformed)
    );
    let without_crc = text.replace(&format!("{checksum}\n"), "");
    key.verify(DATA, without_crc.as_bytes()).unwrap();
    // GnuPG writes no armor headers, so none is admitted.
    let with_header = text.replacen("-----\n", "-----\nComment: release\n", 1);
    assert_eq!(
        key.verify(DATA, with_header.as_bytes()),
        Err(SignatureError::Malformed)
    );
    let after_end = format!("{text}x\n");
    assert!(key.verify(DATA, after_end.as_bytes()).is_err());
    let rearmored = armor(&packet_bytes("good-sha512"), "SIGNATURE");
    key.verify(DATA, &rearmored).unwrap();
}

#[test]
fn every_signed_or_framing_field_is_bound() {
    let key = good();
    let original = packet_bytes("good-sha512");
    // Old-format tag 2 with a two-byte length, then the v4 body.
    assert_eq!(&original[..1], &[0x89]);
    let body = 3;
    let hashed = usize::from(u16::from_be_bytes([original[body + 4], original[body + 5]]));
    let unhashed_at = body + 6 + hashed;
    let unhashed = usize::from(u16::from_be_bytes([
        original[unhashed_at],
        original[unhashed_at + 1],
    ]));
    let left16 = unhashed_at + 2 + unhashed;
    type Mutation<'a> = Box<dyn Fn(&mut Vec<u8>) + 'a>;
    let cases: Vec<(&str, Mutation)> = vec![
        ("version", Box::new(|b| b[body] = 5)),
        ("class", Box::new(|b| b[body + 1] = 0x01)),
        ("algorithm", Box::new(|b| b[body + 2] = 17)),
        ("hash", Box::new(|b| b[body + 3] = 9)),
        ("hashed byte", Box::new(move |b| b[body + 8] ^= 1)),
        ("left16", Box::new(move |b| b[left16] ^= 1)),
        ("value", Box::new(|b| *b.last_mut().unwrap() ^= 1)),
        (
            "trailing byte",
            Box::new(|b| {
                b.push(0);
                let length = u16::from_be_bytes([b[1], b[2]]) + 1;
                b[1..3].copy_from_slice(&length.to_be_bytes());
            }),
        ),
        (
            "truncated",
            Box::new(|b| {
                b.pop();
            }),
        ),
        (
            "second packet",
            Box::new(|b| {
                let copy = b.clone();
                b.extend_from_slice(&copy);
            }),
        ),
        (
            "partial length",
            Box::new(|b| {
                let body = b[3..].to_vec();
                *b = vec![0xc2, 0xe0];
                b.extend_from_slice(&body);
            }),
        ),
    ];
    for (name, mutate) in cases {
        let mut bytes = original.clone();
        mutate(&mut bytes);
        assert!(
            key.verify(DATA, &armor(&bytes, "SIGNATURE")).is_err(),
            "{name} mutation verified"
        );
    }

    // A critical unknown hashed subpacket is refused; the same subpacket in
    // the unauthenticated area is ignored.
    let mut critical = original[..body + 4].to_vec();
    let extended = hashed + 3;
    critical.extend_from_slice(&u16::try_from(extended).unwrap().to_be_bytes());
    critical.extend_from_slice(&original[body + 6..unhashed_at]);
    critical.extend_from_slice(&[2, 0x80 | 100, 0]);
    critical.extend_from_slice(&original[unhashed_at..]);
    let length = u16::try_from(critical.len() - 3).unwrap();
    critical[1..3].copy_from_slice(&length.to_be_bytes());
    assert_eq!(
        key.verify(DATA, &armor(&critical, "SIGNATURE")),
        Err(SignatureError::Malformed)
    );
    // An unhashed issuer naming another key is refused.
    let mut other_issuer = original.clone();
    let id = unhashed_at + 2 + 2;
    assert_eq!(other_issuer[id - 1], 16);
    other_issuer[id] ^= 1;
    assert_eq!(
        key.verify(DATA, &armor(&other_issuer, "SIGNATURE")),
        Err(SignatureError::Bad)
    );
}

#[test]
fn truncated_and_corrupted_inputs_never_panic_or_verify() {
    let key = good();
    let original = packet_bytes("good-sha512");
    for end in 0..original.len() {
        assert!(
            key.verify(DATA, &armor(&original[..end], "SIGNATURE"))
                .is_err()
        );
    }
    // Only the critical bit of the unauthenticated issuer's type may change:
    // it still names the pinned key, a subpacket this verifier understands.
    let unhashed_at = 3 + 6 + usize::from(u16::from_be_bytes([original[7], original[8]]));
    assert_eq!(original[unhashed_at + 3], 16);
    for index in (0..original.len()).filter(|index| *index != unhashed_at + 3) {
        let mut bytes = original.clone();
        bytes[index] ^= 0x80;
        assert!(
            key.verify(DATA, &armor(&bytes, "SIGNATURE")).is_err(),
            "byte {index} flip verified"
        );
    }
    let key_bytes = dearmor(GOOD_KEY, "PUBLIC KEY BLOCK").unwrap();
    for end in 0..key_bytes.len() {
        assert!(
            ReleaseKey::import(
                &armor(&key_bytes[..end], "PUBLIC KEY BLOCK"),
                &fingerprint("good")
            )
            .is_err()
        );
    }
}
